<template><div><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb16" /><el-form :inline="true" @submit.prevent="search"><el-form-item :label="bilingual('客户','Client')"><el-select v-model="query.client" clearable filterable remote :remote-method="lookup" style="width:260px"><el-option v-for="item in clients" :key="item.id" :label="item.label" :value="item.id" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" :loading="loading" @click="search">{{bilingual('搜索','Search')}}</el-button></el-form-item></el-form><el-table :data="rows" border row-key="id" v-loading="loading" :empty-text="bilingual('暂无结算记录','No billing runs')"><el-table-column :label="bilingual('客户','Client')" min-width="160"><template #default="scope">{{clientLabel(scope.row.client)}}</template></el-table-column><el-table-column :label="bilingual('结算类型','Mode')" min-width="160"><template #default="scope">{{modeLabel(scope.row.mode)}}</template></el-table-column><el-table-column prop="from" :label="bilingual('开始日期','From date')" width="130" /><el-table-column prop="to" :label="bilingual('结束日期','To date')" width="130" /><el-table-column prop="amount" :label="bilingual('服务端金额','Server amount')" min-width="145" /><el-table-column prop="createdAt" :label="bilingual('生成时间','Created at')" min-width="190" /><el-table-column :label="bilingual('状态','Status')" width="120"><template #default="scope">{{scope.row.status==='COMPLETE'?bilingual('已完成','Complete'):scope.row.status}}</template></el-table-column><el-table-column :label="bilingual('操作','Actions')" width="100" fixed="right"><template #default="scope"><el-button link type="primary" :loading="openingId===scope.row.id" @click="open(scope.row.id)">{{bilingual('查看','View')}}</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
<el-drawer v-model="opened" :title="bilingual('结算详情','Billing run details')" size="min(900px,100%)"><template v-if="detail"><el-descriptions :column="2" border class="mb16"><el-descriptions-item :label="bilingual('客户','Client')">{{clientLabel(detail.client)}}</el-descriptions-item><el-descriptions-item :label="bilingual('结算类型','Mode')">{{modeLabel(detail.mode)}}</el-descriptions-item><el-descriptions-item :label="bilingual('结算期间','Period')">{{detail.from}} — {{detail.to}}</el-descriptions-item><el-descriptions-item :label="bilingual('服务端合计','Server total')">{{detail.amount}}</el-descriptions-item><el-descriptions-item :span="2" :label="bilingual('结算编号','Run ID')">{{detail.id}}</el-descriptions-item></el-descriptions><h3>{{bilingual('计算明细','Calculation entries')}}</h3><el-table :data="detail.entries||[]" border><el-table-column type="expand"><template #default="scope"><div class="details" v-if="scope.row.storageEvidence"><p>{{bilingual('按周期末库存和价格核算；查看各项数量、单价和金额后再确认。','Calculated using closing stock and rates. Check quantities, rates and amounts before confirming.')}}</p><el-table :data="scope.row.breakdown" border><el-table-column :label="bilingual('计费项目','Charge item')" min-width="240"><template #default="line">{{storageLineLabel(line.row.description)}}</template></el-table-column><el-table-column prop="quantity" :label="bilingual('计费数量','Billable quantity')" min-width="130" /><el-table-column prop="rate" :label="bilingual('单价','Rate')" min-width="120" /><el-table-column prop="amount" :label="bilingual('金额','Amount')" min-width="120" /></el-table></div><p v-else class="details">{{bilingual('本项目没有仓储明细','No storage details for this entry')}}</p></template></el-table-column><el-table-column prop="description" :label="bilingual('项目','Description')" min-width="230" /><el-table-column :label="bilingual('类型','Type')" min-width="120"><template #default="scope">{{financeOption(scope.row.type)}}</template></el-table-column><el-table-column prop="orderCount" :label="bilingual('订单数','Order count')" width="110" /><el-table-column prop="amount" :label="bilingual('金额','Amount')" width="140" /><el-table-column prop="currency" :label="bilingual('币种','Currency')" width="100" /></el-table><h3>{{bilingual('结算时生成的费用快照','Charges as recorded in this run')}}</h3><p class="secondary">{{bilingual('这里保留结算时的费用证据；当前开票状态请到费用与账单页面查看。','This is the charge evidence recorded at settlement. Check Charges and invoices for the current invoicing status.')}}</p><el-table :data="detail.charges||[]" border><el-table-column prop="description" :label="bilingual('描述','Description')" min-width="230" /><el-table-column prop="amount" :label="bilingual('金额','Amount')" width="140" /><el-table-column prop="currency" :label="bilingual('币种','Currency')" width="100" /><el-table-column prop="id" :label="bilingual('费用编号','Charge ID')" min-width="200" show-overflow-tooltip /></el-table></template><template #footer><el-button @click="opened=false">{{bilingual('关闭','Close')}}</el-button></template></el-drawer></div></template>
<script setup>
import {reactive,ref,watch,onMounted} from 'vue'
import request from '@/utils/request'
import {getWarehouseLookups} from '@/api/warehouse'
import {bilingual,financeOption,storageLineLabel} from '@/warehouse/i18n'
import {financeRevision} from '@/warehouse/finance'
const query=reactive({pageNum:1,pageSize:20,client:''}),clients=ref([]),rows=ref([]),total=ref(0),loading=ref(false),error=ref(''),detail=ref(null),opened=ref(false),openingId=ref('')
const clientLabel=id=>clients.value.find(item=>item.id===id)?.label||id||'—',modeLabel=value=>value==='Recurring'?bilingual('周期收费','Recurring charges'):value==='OrderTier'?bilingual('订单量阶梯','Order volume tiers'):value==='Storage'?bilingual('仓储费','Storage charges'):value
let generation=0,lookupGeneration=0,detailGeneration=0
async function lookup(q=''){const ticket=++lookupGeneration;try{const result=await getWarehouseLookups('clients',q);if(ticket===lookupGeneration)clients.value=result.data}catch(e){error.value=e.message}}
async function load(){const ticket=++generation;loading.value=true;error.value='';try{const result=await request({url:'/warehouse/finance/billing/runs',method:'get',params:{...query}});if(ticket===generation){rows.value=result.rows;total.value=result.total}}catch(e){if(ticket===generation)error.value=e.message}finally{if(ticket===generation)loading.value=false}}
function search(){query.pageNum=1;load()}
async function open(id){const ticket=++detailGeneration;openingId.value=id;error.value='';try{const result=await request({url:'/warehouse/finance/billing/runs/'+encodeURIComponent(id),method:'get'});if(ticket===detailGeneration){detail.value=result.data;opened.value=true}}catch(e){if(ticket===detailGeneration)error.value=e.message}finally{if(ticket===detailGeneration)openingId.value=''}}
watch(financeRevision,load);onMounted(()=>{load();lookup()})
</script>
<style scoped>.details{padding:12px 20px}.mb16{margin-bottom:16px}h3{font-size:16px;margin:24px 0 12px}.secondary{font-size:13px;color:var(--el-text-color-secondary);line-height:1.6}</style>
